function renderSummary(result, repository) {
  const { packageName, version: version4, tag: tag2, distTag, releaseUrl, published } = result;
  const npmUrl = `https://www.npmjs.com/package/${packageName}/v/${version4}`;
  const onNpm = published.npm === true;
  const headline = result.dryRun ? `Dry run: ${tag2} would be released. Nothing was published.` : onNpm ? `${packageName}@${version4} is published on npm: ${npmUrl}` : `${tag2} is released: ${releaseUrl ?? ""}`;
  if (result.dryRun) {
    return {
      headline,
      markdown: `## \u{1F9EA} Dry run

**${tag2}** would be released. No tag, no Release, nothing published.
`
    };
  }
  const rows = [
    onNpm ? `| npm | \u2705 [\`${packageName}@${version4}\`](${npmUrl}) (dist-tag \`${distTag}\`) |` : "",
    `| GitHub Release | \u2705 [${tag2}](${releaseUrl ?? ""}) |`,
    "| Provenance | \u2705 attested (SLSA) |"
  ].filter(Boolean);
  const markdown = [
    `## \u{1F389} ${onNpm ? `${packageName} ${version4} is published` : `${tag2} is released`}`,
    "",
    "| Where | Link |",
    "| --- | --- |",
    ...rows,
    "",
    "Check the tarball you can download from the Release:",
    "",
    "```bash",
    `gh release download ${tag2} -R ${repository} --pattern '*.tgz'`,
    `gh attestation verify *.tgz --repo ${repository}`,
    "```",
    ""
  ].join("\n");
  return { headline, markdown };
}

